	heldOutBalancedAccuracy: 0.5582,
	heldOutFrequencyStratumTotal: 50,
	heldOutFrequencyStratumCorrect: 32,
	heldOutFrequencyStratumAccuracy: 0.64,
	heldOutFrequencyStratumMajorityAccuracy: 0.36,
	devTotal: 222,
